    height, width = len(grid), len(grid[0])

    eight_rows = sorted([r for r in range(height) if any(grid[r][c] == 8 for c in range(width))])
    eight_gaps = {}
    for r in eight_rows:
        gaps = sorted([c for c in range(width) if grid[r][c] == 0])
        if gaps:
            min_8 = min(c for c in range(width) if grid[r][c] == 8)
            max_8 = max(c for c in range(width) if grid[r][c] == 8)
            gaps = [g for g in gaps if min_8 <= g <= max_8]
        eight_gaps[r] = gaps

    for idx, r in enumerate(eight_rows):
        if idx % 2 == 0:
            for c in eight_gaps.get(r, []):
                grid[r][c] = 2
        else:
            if r > 0:
                for c in range(eight_gaps[r][0], eight_gaps[r][-1] + 1):
                    if grid[r - 1][c] == 0:
                        grid[r - 1][c] = 2

    if len(eight_rows) >= 2:
        first_last_8 = (eight_rows[-2] + eight_rows[-1]) // 2 + 1
    else:
        first_last_8 = 5

    for r in range(height):
        if r == first_last_8 and r not in eight_rows:
            for c in range(width):
                grid[r][c] = 2

    start_row = eight_rows[0]
    start_cols = eight_gaps.get(start_row, [])

    for c in start_cols:
        for r in range(start_row + 1, height):
            if r in eight_rows:
                continue
            if grid[r][c] == 0:
